import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.D7Ov6LBE.js";const p=JSON.parse('{"title":"Crítica Arquitetônica + Revisão do Agendamento Universal","description":"","frontmatter":{},"headers":[],"relativePath":"projetos/critica-agendamento-universal.md","filePath":"projetos/critica-agendamento-universal.md","lastUpdated":null}'),s={name:"projetos/critica-agendamento-universal.md"};function n(i,e,d,c,l,m){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="critica-arquitetonica-revisao-do-agendamento-universal" tabindex="-1">Crítica Arquitetônica + Revisão do Agendamento Universal <a class="header-anchor" href="#critica-arquitetonica-revisao-do-agendamento-universal" aria-label="Permalink to &quot;Crítica Arquitetônica + Revisão do Agendamento Universal&quot;">​</a></h1><blockquote><p><strong>Data</strong>: 2026-08-12 · <strong>Autor</strong>: Bruno Banho + assistente <strong>Propósito</strong>: Revisão honesta do que foi construído, identificação de bugs/design flaws, e decisão sobre o que manter/descartar.</p></blockquote><hr><h2 id="_1-o-que-e-o-agendamento-universal-afinal" tabindex="-1">1. O que é o Agendamento Universal (afinal)? <a class="header-anchor" href="#_1-o-que-e-o-agendamento-universal-afinal" aria-label="Permalink to &quot;1. O que é o Agendamento Universal (afinal)?&quot;">​</a></h2><p>É um sistema de agendamento <strong>genérico, hexagonal, simples</strong> que vive dentro de um ecossistema ERP:</p><ul><li><strong>Primeiro cliente</strong>: clínicas médicas (consultas)</li><li><strong>Arquitetura</strong>: domínio puro TS + Bun, portas + adaptadores (SQLite, ERP mock)</li><li><strong>Regras</strong>: declaradas em pt-BR (<code>regras/agendamento.pt-BR.md</code>), espelhadas em código com golden tests</li><li><strong>Full duplex</strong>: importa catálogo do ERP, exporta eventos de compromisso</li></ul><hr><h2 id="_2-critica-o-que-esta-errado-ou-questionavel" tabindex="-1">2. Crítica: O que está errado ou questionável? <a class="header-anchor" href="#_2-critica-o-que-esta-errado-ou-questionavel" aria-label="Permalink to &quot;2. Crítica: O que está errado ou questionável?&quot;">​</a></h2><h3 id="_2-1-r2-retorno-tem-prioridade-sobre-1a-consulta-e-uma-regra-sem-fundamento" tabindex="-1">2.1. R2 (&quot;Retorno tem prioridade sobre 1ª consulta&quot;) é uma regra sem fundamento <a class="header-anchor" href="#_2-1-r2-retorno-tem-prioridade-sobre-1a-consulta-e-uma-regra-sem-fundamento" aria-label="Permalink to &quot;2.1. R2 (&quot;Retorno tem prioridade sobre 1ª consulta&quot;) é uma regra sem fundamento&quot;">​</a></h3><p><strong>Problema</strong>: No modelo atual, slots são exclusivos (1 slot = 1 appointment). Se o slot já está booked, a regra R2 nunca se aplica na prática — o slot já foi reservado.</p><p><strong>Impacto</strong>: Código morto em <code>agendarConsulta.ts</code> (linha 49) que tenta buscar &quot;existing appointment&quot; por <code>slotId</code> como se fosse <code>appointmentId</code>.</p><p><strong>Decisão</strong>: Remover R2 do código do UC-02. Se no futuro precisarmos de fila de espera ou overbooking, R2 vira uma política de fila, não de prioridade sobre slot exclusivo.</p><h3 id="_2-2-dominio-incompleto" tabindex="-1">2.2. Domínio incompleto <a class="header-anchor" href="#_2-2-dominio-incompleto" aria-label="Permalink to &quot;2.2. Domínio incompleto&quot;">​</a></h3><p><strong>Problema</strong>: <code>Schedule</code> e <code>Practitioner</code> existem no modelo mas não são entidades de primeira classe. <code>Patient</code> tem só 2 campos.</p><p><strong>Impacto</strong>: O canônico FHIR-inspired está pela metade.</p><p><strong>Decisão</strong>: Expandir o domínio, mas manter simplicidade (não criar 50 entidades de uma vez).</p><h3 id="_2-3-evento-de-remarcacao-com-kind-appointment-created" tabindex="-1">2.3. Evento de remarcação com <code>kind: &#39;appointment.created&#39;</code> <a class="header-anchor" href="#_2-3-evento-de-remarcacao-com-kind-appointment-created" aria-label="Permalink to &quot;2.3. Evento de remarcação com `kind: &#39;appointment.created&#39;`&quot;">​</a></h3><p><strong>Problema</strong>: <code>remarcarConsulta.ts</code> (linha 43) usa <code>kind: &#39;appointment.created&#39;</code> para um evento de remarcação. O ERP não consegue distinguir &quot;criou&quot; de &quot;moveu&quot;.</p><p><strong>Impacto</strong>: Full duplex quebrado — o ERP não sabe que o compromisso mudou de horário.</p><p><strong>Decisão</strong>: Mudar para <code>kind: &#39;appointment.moved&#39;</code> (novo kind) ou <code>kind: &#39;appointment.updated&#39;</code>.</p><h3 id="_2-4-sincronizarerp-e-sincrono-e-sem-retry" tabindex="-1">2.4. SincronizarERP é síncrono e sem retry <a class="header-anchor" href="#_2-4-sincronizarerp-e-sincrono-e-sem-retry" aria-label="Permalink to &quot;2.4. SincronizarERP é síncrono e sem retry&quot;">​</a></h3><p><strong>Problema</strong>: <code>sincronizarERP.ts</code> faz <code>importCatalog()</code> e <code>syncEvents()</code> de forma atômica. Se o ERP estiver offline, a sincronização falha e os eventos não são reenviados.</p><p><strong>Impacto</strong>: Perda de eventos em caso de falha de rede.</p><p><strong>Decisão</strong>: Adicionar retry exponencial + dead-letter queue.</p><h3 id="_2-5-server-ts-importa-de-tests" tabindex="-1">2.5. Server.ts importa de <code>tests/</code> <a class="header-anchor" href="#_2-5-server-ts-importa-de-tests" aria-label="Permalink to &quot;2.5. Server.ts importa de `tests/`&quot;">​</a></h3><p><strong>Problema</strong>: <code>src/http/server.ts</code> importa <code>MemoryAgenda</code>, <code>MemoryErp</code> de <code>../../tests/memory.ts</code>. Camada de produção depende de código de teste.</p><p><strong>Impacto</strong>: Anti-hexagonal. Se removermos os tests, o servidor quebra.</p><p><strong>Decisão</strong>: Mover os adapters in-memory para <code>src/adapters/memory.ts</code> e importar de lá.</p><h3 id="_2-6-sem-foundation-real-persistencia-auth-erp-real" tabindex="-1">2.6. Sem foundation real (persistência, auth, ERP real) <a class="header-anchor" href="#_2-6-sem-foundation-real-persistencia-auth-erp-real" aria-label="Permalink to &quot;2.6. Sem foundation real (persistência, auth, ERP real)&quot;">​</a></h3><p><strong>Problema</strong>: O projeto tem SQLite (<code>SqliteAgenda</code>) mas o servidor ainda usa <code>MemoryAgenda</code> no seed demo. Não há migration, seed real, nem Supabase conectado.</p><p><strong>Decisão</strong>: Conectar o Supabase como adapter real de persistência + auth.</p><h3 id="_2-7-lock-otimista-no-sqlite-esta-correto-mas-nao-testa-concorrencia-real" tabindex="-1">2.7. Lock otimista no SQLite está correto, mas não testa concorrência real <a class="header-anchor" href="#_2-7-lock-otimista-no-sqlite-esta-correto-mas-nao-testa-concorrencia-real" aria-label="Permalink to &quot;2.7. Lock otimista no SQLite está correto, mas não testa concorrência real&quot;">​</a></h3><p><strong>Problema</strong>: O teste <code>sqlite.test.ts</code> usa <code>Promise.all([bookSlot(&#39;a&#39;, 1), bookSlot(&#39;a&#39;, 1)])</code> mas o SQLite em memória é single-threaded no Node — a concorrência real (2 processos) não é testada.</p><p><strong>Decisão</strong>: Teste OK para o modelo atual (Bun.serve é single-threaded event loop). Se precisarmos de multi-processo, usar advisory locks do Postgres.</p><hr><h2 id="_3-critica-ao-intraclinica-ng" tabindex="-1">3. Crítica ao Intraclinica-ng <a class="header-anchor" href="#_3-critica-ao-intraclinica-ng" aria-label="Permalink to &quot;3. Crítica ao Intraclinica-ng&quot;">​</a></h2><p><strong>Veredito</strong>: Não, não vale a pena manter aquele trajeto.</p><h3 id="problemas-estruturais" tabindex="-1">Problemas estruturais: <a class="header-anchor" href="#problemas-estruturais" aria-label="Permalink to &quot;Problemas estruturais:&quot;">​</a></h3><ol><li><strong>Monolito frontend-first</strong>: Angular 22 + Supabase direto (sem camada de domínio). Qualquer mudança de regra de negócio toca em 5+ lugares (componente, store, migration, seed, teste E2E).</li><li><strong>AGENTS.md de 62KB</strong>: Documentação maior que o código. Processo pesado (Hive, worktree RAM constraints, vitest só após merge, ng build proibido em workers) para um projeto de 806 commits que ainda está em &quot;pre-MVP&quot; com resets destrutivos de DB.</li><li><strong>Node divergente</strong>: CI usa Node 22 LTS, dev usa Node 25.9. Não documentado como &quot;escolha&quot;, mas como &quot;fato consumado&quot;.</li><li><strong>Testes em tarefa separada</strong>: Unidade escrita só após merge — significa que código quebrado pode ficar na branch por horas.</li><li><strong>Docker E2E controlado por recurso</strong>: Playwright em Docker com mem_limit/cpus. Funciona, mas adiciona complexidade operacional para um projeto que poderia ter E2E simples.</li><li><strong>Sem canônico</strong>: O frontend fala diretamente com o Supabase (tabelas <code>vw_*</code>). Não há camada de tradução — se o ERP mudar, o frontend quebra.</li></ol><h3 id="o-que-o-agendamento-universal-faz-diferente-e-melhor" tabindex="-1">O que o agendamento-universal faz diferente (e melhor): <a class="header-anchor" href="#o-que-o-agendamento-universal-faz-diferente-e-melhor" aria-label="Permalink to &quot;O que o agendamento-universal faz diferente (e melhor):&quot;">​</a></h3><ul><li><strong>Domínio puro de 300 linhas</strong>: Regras em pt-BR, golden tests, zero dependências externas.</li><li><strong>Hexagonal de verdade</strong>: Portas + adaptadores substituíveis. SQLite hoje, Postgres amanhã, TISS/FHIR depois.</li><li><strong>E2E em 1 arquivo, 8 testes</strong>: 7 API + 1 browser demo. Sem Docker, sem worktree, sem Hive.</li><li><strong>Full duplex com eventos</strong>: Import/export de catálogo, idempotência por chave, fila de eventos.</li><li><strong>Simples primeiro</strong>: 5 UC mínimos, cada um testável isoladamente.</li></ul><hr><h2 id="_4-decisoes-tomadas" tabindex="-1">4. Decisões tomadas <a class="header-anchor" href="#_4-decisoes-tomadas" aria-label="Permalink to &quot;4. Decisões tomadas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problema</th><th>Decisão</th><th>Implementado?</th></tr></thead><tbody><tr><td>R2 sem fundamento</td><td>Remover do UC-02</td><td>✅</td></tr><tr><td>Evento de remarcação com kind errado</td><td>Mudar para <code>appointment.moved</code></td><td>✅</td></tr><tr><td>Server.ts importa de tests/</td><td>Mover adapters para <code>src/adapters/memory.ts</code></td><td>✅</td></tr><tr><td>Sem foundation real</td><td>Conectar Supabase como adapter</td><td>⬜</td></tr><tr><td>SincronizarERP sem retry</td><td>Adicionar retry exponencial</td><td>⬜</td></tr><tr><td>Domínio incompleto</td><td>Expandir <code>Schedule</code> e <code>Practitioner</code></td><td>⬜</td></tr></tbody></table><hr><h2 id="_5-proximos-passos-revisados" tabindex="-1">5. Próximos passos (revisados) <a class="header-anchor" href="#_5-proximos-passos-revisados" aria-label="Permalink to &quot;5. Próximos passos (revisados)&quot;">​</a></h2><ol><li>✅ Remover R2 do UC-02 + corrigir evento de remarcação</li><li>✅ Mover adapters in-memory para <code>src/adapters/memory.ts</code></li><li>⬜ Conectar Supabase (adapter real + auth)</li><li>⬜ Adicionar retry no SincronizarERP</li><li>⬜ Expandir domínio (Schedule, Practitioner completos)</li><li>⬜ LLM design-time: regras pt-BR → código (golden tests como contrato)</li></ol><hr><h2 id="_6-veredito-final" tabindex="-1">6. Veredito final <a class="header-anchor" href="#_6-veredito-final" aria-label="Permalink to &quot;6. Veredito final&quot;">​</a></h2><p>O agendamento-universal está no caminho certo. A arquitetura hexagonal + domínio puro + golden tests é a abordagem correta. O intraclinica-ng, apesar do esforço, é um exemplo do que <strong>não</strong> fazer: monolito frontend-first, processo pesado, sem camada de domínio.</p><p><strong>Próximo passo</strong>: Conectar o Supabase como foundation real (persistência + auth), e só depois expandir para ERP real (TISS/FHIR).</p>',51)])])}const g=o(s,[["render",n]]);export{p as __pageData,g as default};
